transforms.code:
#The Tooling section: shown only for a Production event on an asset that uses tooling. A row per required tooling of the
#item on the machine: a required tool is shown, a required tooling type can take the planner's pick (custom.values.toolPicks,
#saved with the event; none = the scheduler picks a free tool). A saved event shows its reserved tools and their conflicts.
asset = value['assetId']
hidden = {'usesTooling': False, 'rows': [], 'note': '', 'warnings': '', 'warningColor': ''}
if asset is None or value['modeName'] != 'Production': return hidden
if not system.kanoa.utilities.getFieldValue('usesTooling', system.kanoa.asset.getAssets({'assetId': asset})): return hidden
if value['itemId'] is None: return {'usesTooling': True, 'rows': [], 'note': 'Pick an item to see its required tooling.', 'warnings': '', 'warningColor': ''}
toJSON = system.kanoa.utilities.convertDatasetToJSON
blockId = value['scheduleBlockId']
#Saved as it is: its reservations are for this asset and item
saved = blockId is not None and not value['duplicate'] and value['assetId'] == value['origAssetId'] and value['itemId'] == value['origItemId'] \
	and value['workOrderId'] == value['origWorkOrderId']
canEdit = bool(value['canUpdate'] if blockId is not None else value['canCreate'])
picks = dict((p['itemAssetToolingId'], p['toolingAssetId']) for p in (value['toolPicks'] or []))
reqs = [r for r in toJSON(system.kanoa.tooling.getRequiredTooling({'itemId': value['itemId'], 'assetId': asset, 'enabled': True})) if r['required']]
reservations = []
conflicts = []
if saved:
	reservations = [r for r in toJSON(system.kanoa.tooling.getReservations({'scheduleBlockId': blockId})) if r['status'] != 'released']
	now = system.date.now()
	if value['rruleStr']: start, end = now, system.date.addDays(now, 28)
	else: start, end = system.date.addDays(value['startDate'], -1), system.date.addDays(value['endDate'], 1)
	conflicts = [c for c in toJSON(system.kanoa.tooling.getToolingConflicts({'scheduleBlockId': blockId, 'startDate': start, 'endDate': end}))
				 if c['severity'] in ('hard', 'soft')]
def row(requirement, requirementId, options, toolId, editable=False, hint='', rowConflicts=[], placeholder='Any free tool'):
	rowConflicts = sorted(rowConflicts, key=lambda c: 0 if c['severity'] == 'hard' else 1)
	messages = []
	for c in rowConflicts:
		if c['message'] not in messages: messages.append(c['message'])
	message = messages[0] if messages else ''
	if len(messages) > 1: message += ' (+%d more)' % (len(messages) - 1)
	return {'requirement': requirement, 'itemAssetToolingId': requirementId, 'options': options, 'toolingAssetId': toolId, 'editable': editable,
			'hint': hint, 'placeholder': placeholder, 'message': message, 'messages': '\n'.join(messages),
			'severity': rowConflicts[0]['severity'] if rowConflicts else ''}
toolsByType = {}
def tools(typeId):
	if typeId not in toolsByType:
		toolsByType[typeId] = [{'value': t['toolingAssetId'], 'label': t['assetName']}
								for t in toJSON(system.kanoa.tooling.getTools({'assetTypeId': typeId, 'mountableOn': asset, 'enabled': True}))]
	return toolsByType[typeId]
unfilled = [c for c in conflicts if c['toolingAssetId'] is None]
rows = []
for req in reqs:
	reserved = [r for r in reservations if r['itemAssetToolingId'] == req['itemAssetToolingId']]
	reservedId = reserved[0]['toolingAssetId'] if reserved else None
	if req['toolingAssetId']:
		rows.append(row(req['toolingTypeName'] or 'Tool', req['itemAssetToolingId'], [{'value': req['toolingAssetId'], 'label': req['toolingName']}],
						req['toolingAssetId'], hint="The item needs this %s here. Change it in the item's required tooling." % (req['toolingTypeName'] or 'tool'),
						rowConflicts=[c for c in conflicts if c['toolingAssetId'] == req['toolingAssetId']]))
		continue
	options = list(tools(req['toolingAssetTypeId']))
	if reserved and reservedId not in [o['value'] for o in options]: options = [{'value': reservedId, 'label': reserved[0]['toolingName']}] + options
	toolId = picks[req['itemAssetToolingId']] if req['itemAssetToolingId'] in picks else reservedId
	mine = [c for c in conflicts if c['toolingAssetId'] == reservedId] if reserved else unfilled
	if toolId != reservedId: mine = []	#A new pick: checked when the event is saved
	hint = 'The item needs a %s here: pick one, or leave it blank and the scheduler picks a free one.' % req['toolingTypeName']
	if value['rruleStr']: hint += ' A tool picked here is used for every occurrence.'
	rows.append(row(req['toolingTypeName'], req['itemAssetToolingId'], options, toolId, editable=canEdit, hint=hint, rowConflicts=mine))
#Reserved by hand (a script), not from a requirement
for r in reservations:
	if r['itemAssetToolingId'] is None:
		rows.append(row('Added by hand', None, [{'value': r['toolingAssetId'], 'label': r['toolingName']}], r['toolingAssetId'], hint='Reserved by a script, not by the required tooling',
						rowConflicts=[c for c in conflicts if c['toolingAssetId'] == r['toolingAssetId']]))
note = '' if rows else 'No required tooling is set up for this item on this machine.'
warnings = []
for r in rows:
	for m in r['messages'].split('\n') if r['messages'] else []:
		if m not in warnings: warnings.append(m)
hard = any(r['severity'] == 'hard' for r in rows)
return {'usesTooling': True, 'rows': rows, 'note': note, 'warnings': '\n'.join(warnings), 'warningColor': 'var(--kcRed)' if hard else 'var(--kcOrange)'}

